+import type {WebSocket} from 'ws';
+import {createMessageHandler} from './messageHandler.js';
+import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
+import type {ChatSession} from '../../types/session.js';
+import type {OutgoingMessage} from '../../types/messages.js';
+import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../../types/sessionStore.js';
+import {setLogger} from '../../shared/logger.js';
+
+interface LoggedEntry {
+  level: string;
+  category: string;
+  message: string;
+  fields?: Record<string, unknown>;
+}
+
+const idleOrchestrator = {
+  async *processMessageStream() {
+    // list_sessions never invokes the orchestrator stream.
+  },
+} as unknown as ChatOrchestrator;
+
+describe('handling list_sessions in createMessageHandler', () => {
+  const logged: LoggedEntry[] = [];
+
+  beforeEach(() => {
+    logged.length = 0;
+    const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
+      void logged.push({level, category, message, fields});
+    setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
+  });
+
+  afterEach(() => {
+    setLogger();
+  });
+
+  it('answers list_sessions for the session owner with ISO dates, empty list when omitted, and SERVER_ERROR on failure', async () => {
+    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
+    const summaries: SessionSummary[] = [
+      {
+        sessionId: 's2',
+        createdAt: new Date('2026-01-01T00:00:00.000Z'),
+        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
+        entryCount: 4,
+      },
+    ];
+    const listingStore: SessionStore = {
+      ...fiveMemberStore(),
+      listFor: (userId, options) => {
+        seen.push({userId, options});
+        return summaries;
+      },
+    };
+    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
+
+    const listed = await sendFrame(createMessageHandler(idleOrchestrator, listingStore), {
+      type: 'list_sessions',
+      limit: 10,
+      before,
+      userId: 'u2',
+    });
+    const omittedStore = await sendFrame(createMessageHandler(idleOrchestrator), {type: 'list_sessions'});
+    const minimalStore = await sendFrame(createMessageHandler(idleOrchestrator, fiveMemberStore()), {
+      type: 'list_sessions',
+    });
+    const failingStore: SessionStore = {
+      ...fiveMemberStore(),
+      listFor: () => Promise.reject(new Error('database offline')),
+    };
+    const failed = await sendFrame(createMessageHandler(idleOrchestrator, failingStore), {type: 'list_sessions'});
+    const malformed = await sendFrame(createMessageHandler(idleOrchestrator, listingStore), {
+      type: 'list_sessions',
+      limit: -1,
+    });
+    const wsErrors = logged.filter(entry => entry.level === 'error' && entry.category === 'ws');
+
+    expect({seen, listed, omittedStore, minimalStore, failed, malformed, wsErrors}).toEqual({
+      seen: [{userId: 'u1', options: {limit: 10, before}}],
+      listed: [
+        {
+          type: 'session_list',
+          sessions: [
+            {
+              sessionId: 's2',
+              createdAt: '2026-01-01T00:00:00.000Z',
+              updatedAt: '2026-01-01T00:02:00.000Z',
+              entryCount: 4,
+            },
+          ],
+        },
+      ],
+      omittedStore: [{type: 'session_list', sessions: []}],
+      minimalStore: [{type: 'session_list', sessions: []}],
+      failed: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
+      malformed: [{type: 'error', code: 'INVALID_MESSAGE', message: expect.any(String)}],
+      wsErrors: [
+        {
+          level: 'error',
+          category: 'ws',
+          message: expect.any(String),
+          fields: {userId: 'u1', error: 'database offline'},
+        },
+      ],
+    });
+  });
+});
+
+async function sendFrame(
+  handle: ReturnType<typeof createMessageHandler>,
+  rawFrame: unknown
+): Promise<OutgoingMessage[]> {
+  const sent: OutgoingMessage[] = [];
+  const ws = {
+    send: (payload: string) => void sent.push(JSON.parse(payload) as OutgoingMessage),
+  } as unknown as WebSocket;
+  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
+  await handle(ws, session, rawFrame);
+  return sent;
+}
+
+function fiveMemberStore(): SessionStore {
+  return {
+    create: (sessionId, userId) => ({sessionId, userId, entries: []}),
+    get: () => undefined,
+    delete: () => false,
+    count: () => 0,
+    clear: () => undefined,
+  };
+}
