describe('createServer sessionStore message wiring', () => {
  it('forwards sessionStore to the message handler so list_sessions reads the store', async () => {
    const noop = () => undefined;
    const outbound: unknown[] = [];
    let onMessage: ((raw: string) => void) | undefined;
    const timestamp = new Date('2026-04-01T09:00:00.000Z');
    const asked: Array<{owner: string | number; limit?: number}> = [];
    const store: SessionStore = {
      create: (sessionId, userId) => ({sessionId, userId, entries: []}),
      get: () => undefined,
      delete: () => false,
      count: () => 0,
      clear: noop,
      listFor: (owner, opts) => {
        asked.push({owner, limit: opts?.limit});
        return [{sessionId: 'conv-1', createdAt: timestamp, updatedAt: timestamp, entryCount: 3}];
      },
    };
    const hal = createServer({
      app: noop as unknown as Express,
      wsAuth: jest.fn() as unknown as WsAuthenticator,
      sessionStore: store,
      orchestrator: {} as ChatOrchestrator,
    });
    const socket = {
      userId: 'owner-7',
      isAlive: true,
      pause: noop,
      resume: noop,
      close: noop,
      send: (json: string) => void outbound.push(JSON.parse(json)),
      on: (event: string, listener: (raw: string) => void) => {
        if (event === 'message') onMessage = listener;
      },
    } as unknown as ExtWebSocket;

    setLogger({debug: noop, info: noop, warn: noop, error: noop});
    try {
      hal.wss.emit('connection', socket);
      await settle();
      onMessage?.(JSON.stringify({type: 'list_sessions', limit: 5}));
      await settle();
      hal.wss.emit('close');
    } finally {
      setLogger();
    }

    expect({asked, sessionList: outbound.at(-1)}).toEqual({
      asked: [{owner: 'owner-7', limit: 5}],
      sessionList: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 'conv-1',
            createdAt: '2026-04-01T09:00:00.000Z',
            updatedAt: '2026-04-01T09:00:00.000Z',
            entryCount: 3,
          },
        ],
      },
    });
